// VALIDATION: compile-pass
template<class...> struct V {};
namespace n { template<class...> struct B {}; struct P {}; }
template<template<template<class...> class, class = void> class F>
using A = V<F<n::B>, F<n::B, n::P> >;
template<class> struct first;
template<class T, class U> struct first<V<T, U> > { typedef T type; };
template<class> struct second;
template<class T, class U> struct second<V<T, U> > { typedef U type; };
namespace {
template<template<class...> class, class = void>
struct X {
  struct N {
    typedef int table;
  };
};
typedef second<A<X> >::type Y;
typedef first<A<X> >::type D;
}
typedef Y::N::table R;
template<class> struct I {};
template<class... T> struct Run {
  static void go() { int a[] = { (I<T>(), 0)... }; (void)a; }
};
template<class> struct Apply;
template<class... T> struct Apply<V<T...> > : Run<T...> {};
int main() { Apply<A<X> >::go(); return sizeof(R) != 1; }

namespace std {
template<class T>
T next(T value) { return value; }
}

template<class T>
struct direct_streambuf {
  long* begin;
  long* end;

  int seek_impl(long off) {
    using namespace std;
    long next = off;
    if(next < 0 || next > (end - begin)) {
      return 1;
    }
    return 0;
  }
};

int main() {
  direct_streambuf<int> buffer;
  long values[2] = {0, 0};
  buffer.begin = values;
  buffer.end = values + 2;
  return buffer.seek_impl(1);
}

// VALIDATION: compile-pass
// Forwarding a const array reference must not deduce const into its element type.
template<class M>
void inner(M const&) {
  M copy = {};
  copy[0][0] = 1;
}

template<class M>
void outer(M const& value) {
  inner(value);
}

int main() {
  int value[2][2] = {};
  outer(value);
}

// VALIDATION: compile-pass
// A fixed forwarding-reference function template must beat a catch-all
// trailing-pack fallback when both candidates have equal conversion ranks.

template<typename T>
T&& forward_like(T& value)
{
  return static_cast<T&&>(value);
}

struct identity
{
  template<typename T>
  T&& operator()(T&& value) const
  {
    return forward_like<T>(value);
  }
};

struct nat
{
};

template<typename... Args>
nat invoke(Args&&... args);

template<typename F, typename A>
auto invoke(F&& function, A&& argument)
    -> decltype(static_cast<F&&>(function)(static_cast<A&&>(argument)))
{
  return static_cast<F&&>(function)(static_cast<A&&>(argument));
}

long count_chars(char * first, char * last, const char& value, identity project)
{
  long result = 0;
  for(; first != last; ++first) {
    if(invoke(project, *first) == value) {
      ++result;
    }
  }
  return result;
}

int main()
{
  char data[3] = {'a', 'b', 'a'};
  return count_chars(data, data + 3, data[0], identity()) == 2 ? 0 : 1;
}

template<class T, int M, int N> int depth(T (&)[M][N]) { return 2; }
template<class T, int N> int depth(T (&)[N]) { return 1; }
int main() { int a[1][1] = {}; return depth(a) == 2 ? 0 : 1; }

// VALIDATION: compile-pass

typedef unsigned long size_t;

template<class T>
struct range_iterator;

template<class T, size_t N>
struct range_iterator<T[N]>
{
  typedef T * type;
};

template<class T, size_t N>
struct range_iterator<const T[N]>
{
  typedef const T * type;
};

template<class I, class S, class T>
I find_first(I first, S, const T &)
{
  return first;
}

template<class T, size_t N>
T * range_begin(T (&a)[N])
{
  return a;
}

template<class T, size_t N>
const T * range_begin(const T (&a)[N])
{
  return a;
}

template<class R>
typename range_iterator<R>::type begin(R & r)
{
  return range_begin(r);
}

template<class R>
typename range_iterator<const R>::type begin(const R & r)
{
  return range_begin(r);
}

template<class Range, class T>
typename range_iterator<Range>::type find_not(Range & r, const T & x)
{
  return find_first(begin(r), begin(r), x);
}

int main()
{
  int data[5] = {1, 2, 3, 4, 5};
  int * first = find_not(data, 0);
  return first == data ? 0 : 1;
}

template<bool, class T = void>
struct enable_if {};

template<class T>
struct enable_if<true, T> {
  typedef T type;
};

template<bool B, class T = void>
using enable_if_t = typename enable_if<B, T>::type;

struct Policy {};

template<class T>
struct is_ptr {
  static const bool value = false;
};

template<class T>
struct is_ptr<T*> {
  static const bool value = true;
};

template<class T>
struct iterator_traits;

template<class T>
struct iterator_traits<T*> {
  typedef long difference_type;
};

template<class I>
using iter_diff_t = typename iterator_traits<I>::difference_type;

template<class A, class B>
struct Pair {
  A first;
  B second;
};

template<class P>
struct IterOps {
  template<class Iter>
  using difference_type = iter_diff_t<Iter>;
};

template<class P, class In, class Out, enable_if_t<is_ptr<In>::value, int> = 0>
Pair<In, Out> helper(In first, typename IterOps<P>::template difference_type<In> n, Out result) {
  Pair<In, Out> p = {first, result};
  return p;
}

template<class P, class In, class Out, enable_if_t<!is_ptr<In>::value, int> = 0>
Pair<In, Out> helper(In first, typename IterOps<P>::template difference_type<In> n, Out result) {
  Pair<In, Out> p = {first, result};
  return p;
}

int main() {
  char src_buf[2] = {'a', 'b'};
  char dst_buf[2] = {};
  char* src = src_buf;
  char* dst = dst_buf;
  return helper<Policy>(src, iter_diff_t<char*>(2), dst).second - dst;
}

