// VALIDATION: compile-pass
// A constructor-template symbol preserves an unqualified namespace constant
// in its dependent non-type parameter type.

static const unsigned long dynamic_extent = (unsigned long)-1;

template<bool B, class T = void>
struct enable_if
{
};

template<class T>
struct enable_if<true, T>
{
  typedef T type;
};

template<class From, class To>
struct is_convertible
{
  static const bool value = true;
};

template<class T, unsigned long Extent = dynamic_extent>
struct span
{
  template<class I,
           typename enable_if<Extent == dynamic_extent &&
                                  is_convertible<I, T>::value,
                              int>::type = 0>
  span(I *, unsigned long count)
    : size(count)
  {
  }

  unsigned long size;
};

int main()
{
  const char text[] = "hello";
  span<const char> value(text, 5);
  return value.size == 5 ? 0 : 1;
}

// VALIDATION: run-pass
// N3485 focus: 14.8.2 [temp.deduct], constructor-template deduction with a
// non-deduced braced argument followed by an array-bound deduction argument.

typedef unsigned long size_t;

struct storage_ptr {
  int tag;
  storage_ptr() : tag(5) {}
};

struct parse_options {
  int max_depth;
};

struct stream_parser {
  int value;

  template<size_t N>
  stream_parser(storage_ptr sp,
                parse_options const&,
                unsigned char (&buffer)[N])
      : value((int)N + sp.tag + (buffer[0] == 0 ? 0 : 1000))
  {
  }
};

int main()
{
  parse_options opts = {1};
  unsigned char parser_buf[17] = {};
  stream_parser p({}, opts, parser_buf);
  return p.value == 22 ? 0 : 1;
}

